{
  "chapter_proposals": [
    {
      "chapter_id": "CH2",
      "title": "设计机制：色散补偿策略与效率权衡的微观起源",
      "purpose": "揭示不同纳米结构设计（波导型 vs. 共振型）在实现可见光消色差时的内在物理机制，重点解析为何追求宽带宽和高效率的设计往往伴随着对入射角度的敏感性或制造复杂性的增加。本章旨在建立‘设计自由度’与‘效率损失机制’之间的因果联系，解释斜入射下效率下降的微观根源，并评估离散波长复用等替代方案的可行性。",
      "scope": "聚焦于局部相位调控超构透镜的两种主要设计范式：基于传播相位的波导型结构和基于几何/共振相位的共振型结构。分析范围涵盖正入射至中等斜入射角度下的模式耦合行为、对称性破缺效应、以及高数值孔径（NA）下元原子尺寸变化带来的局部效率非均匀性。不包括非局部超表面或多元件复合系统的详细设计流程，仅将其作为解决单界面局限性的背景提及。",
      "excluded_source_handles": [],
      "substantive_threads": [
        {
          "theme": "波导型与共振型设计的根本权衡：偏振敏感性与角度容忍度",
          "argument": "对比两类核心设计机制：波导型（传播相位）利用纳米柱作为截断波导，通过改变截面尺寸调节有效折射率，其优势在于对偏振不敏感且在较宽角度范围内保持较高的模式纯度，但色散调控能力受限于材料本身的色散特性，需依赖复杂的截面形状优化；共振型（几何相位/共振相位）利用各向异性单元或 Mie 共振，能在亚波长尺度实现剧烈的相位突变和灵活的色散工程，但在正入射下的高效率往往建立在严格的对称性条件上，导致其在斜入射时面临固有的效率衰减风险。",
          "evidence_basis": "P0001 对历史高效器件（如 Lal99 的波导型设计）与新型共振设计的对比分析，指出波导型在斜入射下无阴影效应且效率稳定，而共振型虽在正入射下表现优异，却引入了新的角度依赖性。"
        },
        {
          "theme": "斜入射效率下降的微观机制：对称性破缺与反对称模式激发",
          "argument": "深入解析共振型超构透镜（特别是基于 Huygens' 条件的全透射设计）在斜入射下效率骤降的物理根源。论证当入射光具有横向波矢量分量时，原本因空间对称性不匹配而被禁戒的‘反对称模式’（anti-symmetric mode）被激活。该模式通常对应强烈的散射或吸收损耗，表现为透射谱中的显著谷值（dips）。这一机制解释了为何旨在消除反射的对称共振结构，在非垂直入射条件下反而会成为效率损失的源头，且该效应具有强烈的偏振依赖性（TE/TM 分裂）。",
          "evidence_basis": "P0001 引用 Dec15 的理论模型及傅里叶模态法计算结果，展示了 Si 纳米盘阵列在小角度斜入射下，因反对称模式激发导致的透射率凹陷，明确了这是共振型设计的内禀缺陷而非制造误差。"
        },
        {
          "theme": "衍射效率的 sinc²依赖性与焦距 - 波长解耦挑战",
          "argument": "讨论将超构透镜视为广义衍射元件时的效率限制。分析传统衍射光学中效率随相位量化误差呈 sinc²函数下降的规律，指出在消色差设计中，为了同时满足多个波长的聚焦需求，往往需要牺牲单一波长的理想相位剖面，导致整体衍射效率受限。进一步探讨‘焦距与波长解耦’的难点：理想的消色差要求焦距不随波长变化，但这与天然的材料色散和几何相位色散相悖，迫使设计者采用离散波长复用或多层堆叠策略，从而显著增加了设计自由度的消耗和制造复杂性。",
          "evidence_basis": "P0001 关于衍射元件效率极限的讨论，以及对离散波长复用方案（如三波长优化）在实际应用中面临的带宽连续性和旁瓣抑制问题的分析。"
        },
        {
          "theme": "高 NA 设计中的局部效率非均匀性与制造公差敏感度",
          "argument": "分析在高数值孔径（High-NA）设计中，从中心到边缘元原子尺寸的剧烈变化对局部效率的影响。指出边缘区域（对应大入射角和大相位梯度）通常需要极小或极大的特征尺寸，这不仅接近光刻工艺的分辨率极限，导致制造误差敏感性急剧上升，还可能引发高阶模式的意外耦合。论证这种局部效率的非均匀性会导致全孔径平均效率被边缘低效区拉低，且在大视场成像中引入额外的像差和能量损失。",
          "evidence_basis": "P0001 对高 NA 器件（如 Kho16 设计）的边缘区域效率分布的批判性审视，指出全孔径平均值可能掩盖了边缘区域的严重效率衰减，并强调了制造公差在此区域的决定性作用。"
        }
      ],
      "supplement_requests": [],
      "directed_reads": [
        {
          "source_handle": "P0001",
          "focus_areas": [
            "共振型超构透镜斜入射效率下降的反对称模式激发机制（Dec15 模型部分）",
            "波导型（Lal99）与共振型（Kho16）设计在角度容忍度和偏振敏感性上的对比数据",
            "关于‘不恰当比较’的论述中涉及单界面几何像差对高 NA 成像限制的部分",
            "对离散波长复用方案复杂性及 sinc²效率限制的讨论"
          ]
        }
      ],
      "transition_logic": "在阐明了设计机制如何在微观层面引入效率权衡和角度敏感性后，下一章将转向宏观实证层面，审视当前已制备器件的实际性能数据。我们将评估这些实验结果是否触及了本章所述的设计瓶颈，并批判性地分析现有的性能报告标准（如效率定义、成像质量评价指标）是否存在系统性偏差，从而揭示理论潜力与实际表现之间的差距。"
    }
  ],
  "screened_sources": []
}

